<script setup>
import { computed,ref } from 'vue'
import { useRoute } from 'vue-router'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import { clone,incidentOptions,officeOptions,userOptions,today } from './common.js'
const store=useDemo(),route=useRoute(),search=ref(''),status=ref(''),eventFilter=ref(route.query.eventId || ''),dialog=ref(false),draft=ref({}),error=ref(''),removeDialog=ref(false)
const allowed=computed(()=>store.can('investigate') || store.can('enforce'))
const visibleIds=computed(()=>new Set(store.visibleEvents.value.map(e=>e.id)))
const rows=computed(()=>store.visibleRecords('actions').filter(a=>visibleIds.value.has(a.eventId) && (!eventFilter.value || a.eventId===eventFilter.value) && (!status.value || a.status===status.value) && `${a.title} ${a.description}`.toLowerCase().includes((search.value || '').toLowerCase())))
const columns=[{name:'title',label:'Recommendation / action',field:'title',align:'left',sortable:true},{name:'owner',label:'Owner / office',field:'ownerId',align:'left'},{name:'dueDate',label:'Due date',field:'dueDate',align:'left',sortable:true},{name:'status',label:'Status',field:'status',align:'left',sortable:true},{name:'actions',label:'',field:'id'}]
const evidence=computed(()=>store.visibleRecords('evidence').filter(e=>e.eventId===draft.value.eventId))
const reports=computed(()=>store.visibleRecords('reports').filter(r=>r.eventId===draft.value.eventId))
function edit(a){draft.value=a ? clone(a) : {eventId:eventFilter.value || '',reportId:'',title:'',description:'',ownerId:'',officeId:store.currentUser.value?.officeId || '',dueDate:'',status:'open',outcome:'',evidenceIds:[],history:[]};dialog.value=true;error.value=''}
function save(){try{if(!allowed.value)throw Error('Investigation or enforcement permission required.');if(!draft.value.title.trim() || !draft.value.eventId)throw Error('Select an incident and enter an action title.');if(draft.value.status==='completed' && !draft.value.outcome?.trim())throw Error('Record a completion outcome before completing this action.');const data=clone(draft.value);data.history ||= [];data.history.push({status:data.status,actorId:store.currentUser.value?.id,actorName:store.currentUser.value?.name,at:new Date().toISOString(),remarks:data.outcome || 'Action details updated'});data.id ? store.update('actions',data.id,data) : store.add('actions',data);dialog.value=false;error.value=''}catch(e){error.value=e.message}}
function remove(){try{store.remove('actions',draft.value.id);removeDialog.value=false;dialog.value=false}catch(e){error.value=e.message}}
</script>
<template><div class="page-wrap"><PageHeader title="Recommendations and follow-up" subtitle="Assign accountable owners, retain progress and record the evidence supporting completion."><template #actions><q-btn v-if="allowed" color="primary" icon="add" no-caps label="New action" @click="edit()"/></template></PageHeader><div class="panel toolbar-row q-mb-md"><q-input outlined dense clearable v-model="search" label="Search recommendations"/><q-select outlined dense clearable v-model="status" :options="['open','in_progress','completed']" label="Status" style="min-width:180px"/><q-select outlined dense clearable v-model="eventFilter" :options="incidentOptions(store.visibleEvents.value)" emit-value map-options label="Related incident" style="min-width:250px"/><q-space/><span class="muted">{{rows.length}} actions</span></div><div class="panel"><q-table flat :columns="columns" :rows="rows" row-key="id" :pagination="{rowsPerPage:10,sortBy:'dueDate'}"><template #body-cell-title="p"><q-td :props="p"><a href="#" class="record-link" @click.prevent="edit(p.row)">{{p.row.title}}</a><div class="muted">{{store.getEvent(p.row.eventId)?.ref}} · {{p.row.description}}</div></q-td></template><template #body-cell-owner="p"><q-td :props="p">{{store.state.users.find(u=>u.id===p.row.ownerId)?.name || 'Unassigned'}}<div class="muted">{{p.row.officeId || 'Office not assigned'}}</div></q-td></template><template #body-cell-dueDate="p"><q-td :props="p"><span :class="p.row.dueDate && p.row.dueDate<today() && p.row.status!=='completed'?'text-negative':''">{{p.row.dueDate || 'Not assigned'}}</span></q-td></template><template #body-cell-status="p"><q-td :props="p"><StatusBadge :status="p.row.status"/></q-td></template><template #body-cell-actions="p"><q-td :props="p"><q-btn flat no-caps color="primary" :label="allowed?'Update':'View'" @click="edit(p.row)"/></q-td></template></q-table></div>
<q-dialog v-model="dialog"><q-card style="width:800px;max-width:96vw"><q-card-section><div class="text-h6">{{draft.id?'Action details':'New follow-up action'}}</div><q-banner v-if="error" class="bg-red-1 text-negative q-my-md">{{error}}</q-banner><q-form @submit="save" class="q-mt-md"><div class="form-grid"><q-select v-model="draft.eventId" @update:model-value="draft.reportId='';draft.evidenceIds=[]" outlined :options="incidentOptions(store.visibleEvents.value)" emit-value map-options label="Related incident *" :readonly="!allowed"/><q-select v-model="draft.reportId" outlined clearable :options="reports.map(r=>({label:`MAIC ${r.type} revision ${r.revision}`,value:r.id}))" emit-value map-options label="Originating report" :readonly="!allowed"/><q-input v-model="draft.title" outlined label="Action title *" class="span-2" :readonly="!allowed"/><q-input v-model="draft.description" outlined type="textarea" label="Recommendation and required response" class="span-2" :readonly="!allowed"/><q-select v-model="draft.ownerId" outlined clearable :options="userOptions(store)" emit-value map-options label="Responsible account" :readonly="!allowed"/><q-select v-model="draft.officeId" outlined clearable :options="officeOptions(store)" emit-value map-options label="Responsible office" :readonly="!allowed"/><q-input v-model="draft.dueDate" outlined type="date" stack-label label="Due date" :readonly="!allowed"/><q-select v-model="draft.status" outlined :options="['open','in_progress','completed']" label="Status" :readonly="!allowed"/><q-input v-model="draft.outcome" outlined type="textarea" label="Progress / completion outcome" class="span-2" :readonly="!allowed"/><q-select v-model="draft.evidenceIds" outlined multiple use-chips :options="evidence.map(e=>({label:e.name,value:e.id}))" emit-value map-options label="Completion evidence" class="span-2" :readonly="!allowed"/></div><div v-if="draft.history?.length" class="q-mt-lg"><div class="section-title">Action history</div><p v-for="(h,i) in [...draft.history].reverse()" :key="i" class="muted">{{h.at ? new Date(h.at).toLocaleString() : 'Time unknown'}} · {{h.actorName || h.actorId}} · {{h.status}} · {{h.remarks}}</p></div><div class="toolbar-row q-mt-lg"><q-btn v-if="allowed && draft.id" flat color="negative" no-caps label="Delete action" @click="removeDialog=true"/><q-space/><q-btn flat no-caps label="Close" v-close-popup/><q-btn v-if="allowed" color="primary" no-caps label="Save action" type="submit"/></div></q-form></q-card-section></q-card></q-dialog><q-dialog v-model="removeDialog"><q-card><q-card-section>Delete this local demonstration action? Its audit entry remains.</q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" no-caps v-close-popup/><q-btn color="negative" label="Delete" no-caps @click="remove"/></q-card-actions></q-card></q-dialog>
</div></template>
